//save JPG
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 mountains[${N_mountains}];

		const float WIDTH = ${windowWidth}.0;
		var float HEIGHT = ${windowHeight}.0;

		#define PI 3.1415926538

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			for (int i = 0; i < ${N_mountains}; i++) {
				vec3 mtn = mountains[i];
				float dx = mtn.x - x;
				float dy = mtn.y - y;
				float r = mtn.z;
				v += exp(-0.0001 * (dx * dx + dy * dy));
			}

			float value = -1.0 / (cos(v * PI / 0.2) + 0.95);

			if(value > 0.0) gl_FragColor = vec4(0.0, 0, 0.0, 1.0);
			else gl_FragColor = vec4(1, 1, 1, 1);
		}
	`;

	return createShader(vert, frag);
}

